using DocumentFormat.OpenXml.Packaging;
using W=DocumentFormat.OpenXml.Wordprocessing;
using UCE.Application.Documents.Abstractions;
using UCE.Application.Documents.Models;
using UCE.Domain.Enums;
namespace UCE.Infrastructure.Documents.Parsing;
public sealed class DocxDocumentParser(ITextLanguageDetector languageDetector):IDocumentParser
{
 public bool CanParse(string fileName)=>Path.GetExtension(fileName).Equals(".docx",StringComparison.OrdinalIgnoreCase);
 public Task<ParsedDocument> ParseAsync(Stream stream,string fileName,CancellationToken cancellationToken=default){cancellationToken.ThrowIfCancellationRequested();using var word=WordprocessingDocument.Open(stream,false);var body=word.MainDocumentPart?.Document?.Body??throw new InvalidDataException("DOCX document body is missing.");var doc=new ParsedDocument{SourceFileName=Path.GetFileName(fileName),Title=word.PackageProperties.Title??Path.GetFileNameWithoutExtension(fileName),Author=word.PackageProperties.Creator};var textParts=new List<string>();int order=0,position=0;foreach(var element in body.Elements()){if(element is W.Paragraph p){var text=p.InnerText?.Trim()??"";if(text.Length==0)continue;var style=p.ParagraphProperties?.ParagraphStyleId?.Val?.Value;int idx=doc.ParsedParagraphs.Count;doc.ParsedParagraphs.Add(new(){Text=text,Order=order,StartPosition=position,EndPosition=position+text.Length,StyleName=style});doc.Blocks.Add(new(){Order=order++,Kind=ParsedBlockKind.Paragraph,ParagraphIndex=idx});textParts.Add(text);position+=text.Length+2;}else if(element is W.Table table){var parsed=ParseTable(table,doc.Tables.Count);int idx=doc.Tables.Count;doc.Tables.Add(parsed);doc.Blocks.Add(new(){Order=order++,Kind=ParsedBlockKind.Table,TableIndex=idx});var tableText=FormatTable(parsed);textParts.Add(tableText);position+=tableText.Length+2;}}doc.FullText=string.Join("\n\n",textParts);doc.Language=languageDetector.Detect(doc.FullText);return Task.FromResult(doc);}
 private static ParsedTable ParseTable(W.Table table,int order){var parsed=new ParsedTable{Order=order};int r=0,max=0;foreach(var row in table.Elements<W.TableRow>()){var pr=new ParsedTableRow{Index=r};int c=0;foreach(var cell in row.Elements<W.TableCell>()){var text=string.Join(Environment.NewLine,cell.Elements<W.Paragraph>().Select(x=>x.InnerText).Where(x=>!string.IsNullOrWhiteSpace(x))).Trim();int span=cell.TableCellProperties?.GridSpan?.Val?.Value??1;pr.Cells.Add(new(){RowIndex=r,ColumnIndex=c,Text=text,ColumnSpan=Math.Max(1,span)});c+=Math.Max(1,span);}max=Math.Max(max,c);parsed.Rows.Add(pr);r++;}parsed.RowCount=r;parsed.ColumnCount=max;return parsed;}
 private static string FormatTable(ParsedTable table){return string.Join(Environment.NewLine,table.Rows.Select(row=>string.Join(" | ",row.Cells.Select(cell=>cell.Text))));}
}